// countingStore is the store of the session test above: one session, one
// user, everything else of the contract left unused on purpose.
type countingStore struct {
	store.Store
}

func (*countingStore) GetSession(_ context.Context, cookie string) (*store.Session, error) {
	if cookie != "known-session" {
		return nil, store.ErrNotFound
	}
	return &store.Session{Cookie: cookie, UserID: 1, ExpiresAt: time.Now().UTC().Add(time.Hour)}, nil
}

func (*countingStore) GetUserByID(_ context.Context, id int64) (*store.User, error) {
	if id != 1 {
		return nil, store.ErrNotFound
	}
	return &store.User{ID: id, Email: "ada@example.com"}, nil
}
