package server_test

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"git.aisoftwarefactory.world/linkshort2/linkshort2/internal/server"
	"git.aisoftwarefactory.world/linkshort2/linkshort2/internal/sqlite"
	"git.aisoftwarefactory.world/linkshort2/linkshort2/internal/store"
)

// openStore gives the test a real store of its own, so it can put a session
// in it and hand its cookie to the server New wires.
func openStore(t *testing.T) store.Store {
	t.Helper()
	db, err := sqlite.Open(t.TempDir() + "/links.db")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = db.Close() })
	return db
}

// TestSessionMiddlewareNamesTheUser runs the handler New builds over a
// store holding one login: the cookie names its user on GET /api/me, and an
// anonymous or unknown request answers 401.
func TestSessionMiddlewareNamesTheUser(t *testing.T) {
	st := openStore(t)
	ctx := context.Background()
	user, err := st.CreateUser(ctx, "ada@example.com", "hash-not-a-password")
	if err != nil {
		t.Fatal(err)
	}
	const cookie = "a-session-cookie-value"
	if _, err := st.CreateSession(ctx, cookie, user.ID, time.Now().UTC().Add(time.Hour)); err != nil {
		t.Fatal(err)
	}

	srv := httptest.NewServer(server.New(server.Config{Store: st}))
	defer srv.Close()

	me := func(name, value string) (*http.Response, map[string]any) {
		t.Helper()
		req, err := http.NewRequest(http.MethodGet, srv.URL+"/api/me", nil)
		if err != nil {
			t.Fatal(err)
		}
		if value != "" {
			req.AddCookie(&http.Cookie{Name: server.SessionCookie, Value: value})
		}
		res, err := srv.Client().Do(req)
		if err != nil {
			t.Fatal(err)
		}
		defer func() { _ = res.Body.Close() }()
		var body map[string]any
		_ = json.NewDecoder(res.Body).Decode(&body)
		return res, body
	}

	res, body := me("known", cookie)
	if res.StatusCode != http.StatusOK || body["email"] != "ada@example.com" {
		t.Errorf("GET /api/me with a known session: %d %v, want 200 naming the user", res.StatusCode, body)
	}

	res, body = me("unknown", "no-such-session")
	if res.StatusCode != http.StatusUnauthorized {
		t.Errorf("GET /api/me with an unknown session: %d %v, want 401", res.StatusCode, body)
	}

	res, body = me("anonymous", "")
	if res.StatusCode != http.StatusUnauthorized {
		t.Errorf("GET /api/me without a cookie: %d %v, want 401", res.StatusCode, body)
	}
}

