// Package sqlite is the app's Store over a SQLite file at
// $DATA_DIR/links.db, on modernc.org/sqlite (pure Go, no cgo). The schema
// lives in the .sql files under migrations/, embedded with the package,
// applied in name order and remembered in schema_migrations.
package sqlite

import (
	"context"
	"database/sql"
	"embed"
	"errors"
	"fmt"
	"io/fs"
	"path/filepath"
	"sort"
	"strings"
	"time"

	_ "modernc.org/sqlite"

	"git.aisoftwarefactory.world/linkshort2/linkshort2/internal/store"
)

//go:embed migrations/*.sql
var migrations embed.FS

// DB is store.Store over one SQLite file.
type DB struct {
	db *sql.DB
}

// Open prepares the database at path (its directory must exist), applies
// the pending migrations and returns it. It keeps a single connection:
// SQLite takes one writer at a time, and with it a count-then-insert never
// loses a click to another.
func Open(path string) (*DB, error) {
	dsn := "file:" + path + "?_pragma=foreign_keys(1)&_pragma=busy_timeout(5000)&_pragma=journal_mode(WAL)&_pragma=synchronous(FULL)"
	sqlDB, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("sqlite: open %s: %w", path, err)
	}
	sqlDB.SetMaxOpenConns(1)
	sqlDB.SetConnMaxLifetime(0)
	if _, err := sqlDB.Exec(`PRAGMA user_version`); err != nil {
		_ = sqlDB.Close()
		return nil, fmt.Errorf("sqlite: reach %s: %w", path, err)
	}
	d := &DB{db: sqlDB}
	ctx := context.Background()
	if err := d.migrate(ctx); err != nil {
		_ = d.Close()
		return nil, err
	}
	return d, nil
}

// Close releases the database.
func (d *DB) Close() error { return d.db.Close() }

func (d *DB) migrate(ctx context.Context) error {
	if _, err := d.db.ExecContext(ctx,
		`CREATE TABLE IF NOT EXISTS schema_migrations (
			name TEXT PRIMARY KEY,
			applied_at TEXT NOT NULL
		)`); err != nil {
		return fmt.Errorf("sqlite: schema_migrations: %w", err)
	}
	paths, err := fs.Glob(migrations, "migrations/*.sql")
	if err != nil {
		return fmt.Errorf("sqlite: read migrations: %w", err)
	}
	sort.Strings(paths)
	// A migration is remembered by its file name alone, so the directory
	// it is embedded from may move.
	pending := make([]string, len(paths))
	for i, p := range paths {
		pending[i] = filepath.Base(p)
	}
	done := map[string]bool{}
	rows, err := d.db.QueryContext(ctx, `SELECT name FROM schema_migrations`)
