+package server
+
+import (
+	"net"
+	"net/http"
+	"strconv"
+	"strings"
+	"sync"
+	"time"
+
+	"git.aisoftwarefactory.world/linkshort2/linkshort2/internal/store"
+)
+
+// The limits of the API: a client address may try to sign up or log in
+// authMaxAttempts times per authWindow, and a logged-in user may create
+// linkMaxPerHour new links per linkWindow. Beyond either the API answers
+// 429. They are counters in memory keyed by address or user ID, with a TTL:
+// one replica holds them, and a restart forgets who was limited.
+const (
+	authMaxAttempts = 10
+	authWindow      = time.Minute
+	linkMaxPerHour  = 30
+	linkWindow      = time.Hour
+)
+
+// counter is one window of one key: hits counted since start. A window
+// starts with the first attempt it sees, so an idle key costs nothing.
+type counter struct {
+	start time.Time
+	hits  int
+}
+
+// limiter counts attempts per key over a fixed window of window length.
+type limiter struct {
+	mu       sync.Mutex
+	window   time.Duration
+	max      int
+	counters map[string]*counter
+	now      func() time.Time
+	// sweepEvery and sinceSweep keep the map from growing without end:
+	// every sweep-th call to allow drops the keys whose window has passed.
+	sweepEvery int
+	sinceSweep int
+}
+
+func newLimiter(max int, window time.Duration) *limiter {
+	return &limiter{
+		window:     window,
+		max:        max,
+		counters:   map[string]*counter{},
+		now:        time.Now,
+		sweepEvery: 512,
+	}
+}
+
+// allow records one attempt for key and reports whether it stays within the
+// limit. The attempt that passes the limit is not counted, so the window of
+// a key resumes with the next allowed one.
+func (l *limiter) allow(key string) bool {
+	l.mu.Lock()
+	defer l.mu.Unlock()
+	at := l.now()
+	if l.sweepEvery > 0 {
+		l.sinceSweep++
+		if l.sinceSweep >= l.sweepEvery {
+			l.sweepLocked(at)
+		}
+	}
+	c, ok := l.counters[key]
+	if !ok || at.Sub(c.start) >= l.window {
+		l.counters[key] = &counter{start: at, hits: 1}
+		return true
+	}
+	if c.hits >= l.max {
+		return false
+	}
+	c.hits++
+	return true
+}
+
+// remaining reports how many attempts key still has left in its window; a
+// key that never attempted has the whole limit. It answers the Retry-After
+// header of a refused request.
+func (l *limiter) remaining(key string) (left int, retryAfter time.Duration) {
+	l.mu.Lock()
+	defer l.mu.Unlock()
+	at := l.now()
+	c, ok := l.counters[key]
+	if !ok || at.Sub(c.start) >= l.window {
+		return l.max, 0
+	}
+	left = l.max - c.hits
+	if left < 0 {
+		left = 0
+	}
+	return left, c.start.Add(l.window).Sub(at)
+}
+
+// sweepLocked drops the keys whose window has passed. Called with l.mu held.
+func (l *limiter) sweepLocked(at time.Time) {
+	l.sinceSweep = 0
+	for k, c := range l.counters {
+		if at.Sub(c.start) >= l.window {
+			delete(l.counters, k)
+		}
+	}
+}
+
+// reset forgets every counter; a test uses it to start clean.
+func (l *limiter) reset() {
+	l.mu.Lock()
+	defer l.mu.Unlock()
+	l.counters = map[string]*counter{}
+	l.sinceSweep = 0
+}
+
+// Server gains the two counters of the limits, built once per handler.
+func (s *Server) limiters() {
+	if s.authLimit == nil {
+		s.authLimit = newLimiter(authMaxAttempts, authWindow)
+	}
+	if s.linkLimit == nil {
+		s.linkLimit = newLimiter(linkMaxPerHour, linkWindow)
+	}
+}
+
+// rateLimitAuth guards POST /api/signup and POST /api/login: at most
+// authMaxAttempts attempts per minute per client address.
+func (s *Server) rateLimitAuth(next http.HandlerFunc) http.HandlerFunc {
+	return func(w http.ResponseWriter, r *http.Request) {
+		ip := clientIP(r)
+		if !s.authLimit.allow(ip) {
+			s.refuseRateLimited(w, r, s.authLimit, ip, "too many signup or login attempts")
+			return
+		}
+		next(w, r)
+	}
+}
+
+// rateLimitLinks guards POST /api/links: at most linkMaxPerHour new links
+// per hour per logged-in user. An anonymous request reaches next unnamed,
+// and the handler inside answers 401 without costing anything.
+func (s *Server) rateLimitLinks(next func(http.ResponseWriter, *http.Request, *store.User)) http.HandlerFunc {
+	return func(w http.ResponseWriter, r *http.Request) {
+		user, ok := UserFrom(r.Context())
+		if !ok {
+			next(w, r, nil)
+			return
+		}
+		key := userKey(user)
+		if !s.linkLimit.allow(key) {
+			s.refuseRateLimited(w, r, s.linkLimit, key, "too many links created")
+			return
+		}
+		next(w, r, user)
+	}
+}
+
+// refuseRateLimited answers 429 with the seconds until the window of key
+// opens again, so a client knows how long to wait.
+func (s *Server) refuseRateLimited(w http.ResponseWriter, r *http.Request, l *limiter, key string, msg string) {
+	_, retryAfter := l.remaining(key)
+	seconds := int64(retryAfter.Round(time.Second) / time.Second)
+	if seconds < 1 {
+		seconds = 1
+	}
+	w.Header().Set("Retry-After", strconv.FormatInt(seconds, 10))
+	writeError(w, http.StatusTooManyRequests, msg)
+}
+
+// userKey is what the link counter keys a user by.
+func userKey(u *store.User) string {
+	return strconv.FormatInt(u.ID, 10)
+}
+
+// clientIP is the address a request came from, as the rate limiter of the
+// auth routes keys it: the host of RemoteAddr, or the single value of
+// X-Forwarded-For when the proxy in front of the service set one. Anything
+// unparsable falls back to the peer address, which no counter shares.
+func clientIP(r *http.Request) string {
+	if xff := r.Header.Get("X-Forwarded-For"); xff != "" {
+		if first, _, found := strings.Cut(xff, ","); found || first == "" {
+			first = strings.TrimSpace(first)
+			if net.ParseIP(first) != nil {
+				return first
+			}
+		}
+	}
+	if host, _, err := net.SplitHostPort(r.RemoteAddr); err == nil && host != "" {
+		return host
+	}
+	return r.RemoteAddr
+}
