+	l.mu.Lock()
+	defer l.mu.Unlock()
+	at := l.now()
+	if l.sweepEvery > 0 {
+		l.sinceSweep++
+		if l.sinceSweep >= l.sweepEvery {
+			l.sweepLocked(at)
+		}
+	}
+	c, ok := l.counters[key]
+	if !ok || at.Sub(c.start) >= l.window {
+		l.counters[key] = &counter{start: at, hits: 1}
+		return true
+	}
+	if c.hits >= l.max {
+		return false
+	}
+	c.hits++
+	return true
