diff --git a/internal/server/ratelimit.go b/internal/server/ratelimit.go
new file mode 100644
index 0000000..004a823
--- /dev/null
+++ b/internal/server/ratelimit.go
@@ -0,0 +1,210 @@
+package server
+
+import (
+	"net"
+	"net/http"
+	"strconv"
+	"strings"
+	"sync"
+	"time"
+
+	"git.aisoftwarefactory.world/linkshort2/linkshort2/internal/store"
+)
+
+// The limits of the API: a client address may try to sign up or log in
+// AuthMaxAttempts times per authWindow, and a logged-in user may create
+// LinkMaxPerHour new links per linkWindow. Beyond either the API answers
+// 429. They are counters in memory keyed by address or user ID, with a TTL:
+// one replica holds them, and a restart forgets who was limited.
+const (
+	// AuthMaxAttempts is how many signup or login attempts one client
+	// address may make per minute.
+	AuthMaxAttempts = 10
+	// LinkMaxPerHour is how many new links one user may create per hour.
+	LinkMaxPerHour = 30
+
+	authWindow = time.Minute
+	linkWindow = time.Hour
+)
+
+// counter is one window of one key: hits counted since start. A window
+// starts with the first attempt it sees, so an idle key costs nothing.
+type counter struct {
+	start time.Time
+	hits  int
+}
+
+// limiter counts attempts per key over a fixed window of window length.
+type limiter struct {
+	mu       sync.Mutex
+	window   time.Duration
+	max      int
+	counters map[string]*counter
+	now      func() time.Time
+	// sweepEvery and sinceSweep keep the map from growing without end:
+	// every sweep-th call to allow drops the keys whose window has passed.
+	sweepEvery int
+	sinceSweep int
+}
+
+func newLimiter(max int, window time.Duration) *limiter {
+	return &limiter{
+		window:     window,
+		max:        max,
+		counters:   map[string]*counter{},
+		now:        time.Now,
+		sweepEvery: 512,
+	}
+}
+
+// allow records one attempt for key and reports whether it stays within the
+// limit. The attempt that passes the limit is not counted, so the window of
+// a key resumes with the next allowed one.
+func (l *limiter) allow(key string) bool {
+	l.mu.Lock()
+	defer l.mu.Unlock()
+	at := l.now()
+	if l.sweepEvery > 0 {
+		l.sinceSweep++
+		if l.sinceSweep >= l.sweepEvery {
+			l.sweepLocked(at)
+		}
+	}
+	c, ok := l.counters[key]
+	if !ok || at.Sub(c.start) >= l.window {
+		l.counters[key] = &counter{start: at, hits: 1}
+		return true
+	}
+	if c.hits >= l.max {
+		return false
+	}
+	c.hits++
+	return true
+}
+
+// remaining reports how many attempts key still has left in its window, and
+// how long until the window opens again. A key that never attempted, or whose
+// window passed, has the whole limit and no wait. It answers the Retry-After
+// header of a refused request.
+func (l *limiter) remaining(key string) (left int, retryAfter time.Duration) {
+	l.mu.Lock()
+	defer l.mu.Unlock()
+	at := l.now()
+	c, ok := l.counters[key]
+	if !ok || at.Sub(c.start) >= l.window {
+		return l.max, 0
+	}
+	left = l.max - c.hits
+	if left < 0 {
+		left = 0
+	}
+	return left, c.start.Add(l.window).Sub(at)
+}
+
+// sweepLocked drops the keys whose window has passed. Called with l.mu held.
+func (l *limiter) sweepLocked(at time.Time) {
+	l.sinceSweep = 0
+	for k, c := range l.counters {
+		if at.Sub(c.start) >= l.window {
+			delete(l.counters, k)
+		}
+	}
+}
+
+// Server gains the two counters of the limits, built once per handler. New
+// calls it before it builds the routes; a test that builds a Server by hand
+// calls it too.
+func (s *Server) limiters() {
+	if s.authLimit == nil {
+		s.authLimit = newLimiter(AuthMaxAttempts, authWindow)
+	}
+	if s.linkLimit == nil {
+		s.linkLimit = newLimiter(LinkMaxPerHour, linkWindow)
+	}
+}
+
+// NewForTest builds the handler of a card that is not wired into the routes
+// yet: createLink stands for POST /api/links, wrapped in the link limiter
+// and the session middleware exactly as the route would be. It opens no
+// store, so the test brings one. A later card that adds the real route may
+// drop it.
+func NewForTest(st store.Store, createLink func(http.ResponseWriter, *http.Request, *store.User)) http.Handler {
+	s := &Server{store: st, mux: http.NewServeMux()}
+	s.limiters()
+	s.mux.HandleFunc("POST /api/links", s.RateLimitLinks(createLink))
+	return s.session(s.mux)
+}
+
+// RateLimitAuth wraps next in the auth limiter of the card's limits: at most
+// AuthMaxAttempts attempts per minute per client address, 429 beyond. The
+// routes it guards are POST /api/signup and, once the auth card adds it,
+// POST /api/login; New already applies it to signup, so a later handler for
+// either route only has to wrap itself in this.
+func (s *Server) RateLimitAuth(next http.HandlerFunc) http.HandlerFunc {
+	s.limiters()
+	return func(w http.ResponseWriter, r *http.Request) {
+		ip := clientIP(r)
+		if !s.authLimit.allow(ip) {
+			s.refuseRateLimited(w, s.authLimit, ip, "too many signup or login attempts")
+			return
+		}
+		next(w, r)
+	}
+}
+
+// RateLimitLinks wraps next in the link limiter: at most LinkMaxPerHour new
+// links per hour per logged-in user, 429 beyond. It guards POST /api/links,
+// which the links card adds; an anonymous request reaches next unnamed, so
+// its 401 costs the user nothing.
+func (s *Server) RateLimitLinks(next func(http.ResponseWriter, *http.Request, *store.User)) http.HandlerFunc {
+	s.limiters()
+	return func(w http.ResponseWriter, r *http.Request) {
+		user, ok := UserFrom(r.Context())
+		if !ok {
+			next(w, r, nil)
+			return
+		}
+		key := userKey(user)
+		if !s.linkLimit.allow(key) {
+			s.refuseRateLimited(w, s.linkLimit, key, "too many links created")
+			return
+		}
+		next(w, r, user)
+	}
+}
+
+// refuseRateLimited answers 429 with the seconds until the window of key
+// opens again, so a client knows how long to wait.
+func (s *Server) refuseRateLimited(w http.ResponseWriter, l *limiter, key string, msg string) {
+	_, retryAfter := l.remaining(key)
+	seconds := int64(retryAfter.Round(time.Second) / time.Second)
+	if seconds < 1 {
+		seconds = 1
+	}
+	w.Header().Set("Retry-After", strconv.FormatInt(seconds, 10))
+	writeError(w, http.StatusTooManyRequests, msg)
+}
+
+// userKey is what the link counter keys a user by.
+func userKey(u *store.User) string {
+	return strconv.FormatInt(u.ID, 10)
+}
+
+// clientIP is the address a request came from, as the auth limiter keys it:
+// the first address of X-Forwarded-For when the proxy in front of the service
+// set one, otherwise the host of the peer address. A header value that names
+// no address falls back to the peer, so a client cannot share another's
+// counter by writing the header itself.
+func clientIP(r *http.Request) string {
+	if xff := r.Header.Get("X-Forwarded-For"); xff != "" {
+		first, _, _ := strings.Cut(xff, ",")
+		first = strings.TrimSpace(first)
+		if net.ParseIP(first) != nil {
+			return first
+		}
+	}
+	if host, _, err := net.SplitHostPort(r.RemoteAddr); err == nil && host != "" {
+		return host
+	}
+	return r.RemoteAddr
+}
